fn insert_delimiter(numbers: Vec<i8>, delimiter: i8) -> Vec<i8> {
    let n = numbers.len();
    if n <= 1 {
        // If empty or length 1, return unchanged
        return numbers;
    }
    // Result length should be 2*n - 1
    let mut result = Vec::with_capacity(2 * n - 1);

    for (i, &num) in numbers.iter().enumerate() {
        // Insert the original number at even indices in result
        if i > 0 {
            // Insert delimiter before current number except before the first
            result.push(delimiter);
        }
        result.push(num);
    }

    result
}